customEChartConfig:
{{ ((chartType) => ( 
{
  "dataset": {
    "source": [[
      "Team",
      "Priority 1",
      "Priority 2",
      "Priority 3",
      "Priority 4"
    ]].concat(dash_unassignedByTeam_NV.data.reduce((acc, row) => {
      let teamIndex = acc.findIndex(item => item[0] === row.team);
      if (teamIndex === -1) {
        acc.push([row.team, 0, 0, 0, 0]);
        teamIndex = acc.length - 1;
      }
      // Handle null Priority
      if (row.Priority === null) {
        acc[teamIndex][1] = row.CountOftaskID; // Put all Grants tasks in first column
      } else {
        acc[teamIndex][row.Priority] = row.CountOftaskID;
      }
      return acc;
    }, []))
  },
  "tooltip": {
    "trigger": "axis",
    "axisPointer": {
      "type": "shadow"
    }
  },
  "title": {
    "text": "Unassigned Tasks by Team and Priority",
    "left": "center",
    "textStyle": {
      "width": 400,
      "overflow": "truncate"
    }
  },
  "legend": {
    "orient": "horizontal",
    "top": 30
  },
  "grid": {
    "left": "3%",
    "right": "4%",
    "bottom": "3%",
    "top": "15%",
    "containLabel": true
  },
  "xAxis": {
    "type": "value"
  },
  "yAxis": {
    "type": "category"
  },
  "series": [
    {
      "name": "Priority 1",
      "type": "bar",
      "stack": "total",
      "label": {
        "show": true,
        "position": "inside",
        "formatter": function(params) {
          return params.data[1] > 0 ? params.data[1] : '';
        }
      },
      "emphasis": {
        "focus": "series"
      }
    },
    {
      "name": "Priority 2",
      "type": "bar",
      "stack": "total",
      "label": {
        "show": true,
        "position": "inside",
        "formatter": function(params) {
          return params.data[2] > 0 ? params.data[2] : '';
        }
      },
      "emphasis": {
        "focus": "series"
      }
    },
    {
      "name": "Priority 3",
      "type": "bar",
      "stack": "total",
      "label": {
        "show": true,
        "position": "inside",
        "formatter": function(params) {
          return params.data[3] > 0 ? params.data[3] : '';
        }
      },
      "emphasis": {
        "focus": "series"
      }
    },
    {
      "name": "Priority 4",
      "type": "bar",
      "stack": "total",
      "label": {
        "show": true,
        "position": "inside",
        "formatter": function(params) {
          return params.data[4] > 0 ? params.data[4] : '';
        }
      },
      "emphasis": {
        "focus": "series"
      }
    }
  ],
  "color": ["#5470c6", "#91cc75", "#fac858", "#ee6666"]  // Blue, Green, Yellow, Red
}
))(Chart8.chartType) }}
